scripts.bump:version:
node --input-type=module -e "
import { readFileSync, writeFileSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = dirname(fileURLToPath(import.meta.url));
const pkgs = ['package.json', ...['core','http-transport','reporter-junit','snapshot','vitest-plugin'].map(p => 'packages/'+p+'/package.json')];

pkgs.forEach(f => {
  const d = JSON.parse(readFileSync(join(__dirname, f), 'utf8'));
  if (d.private) return;
  const [a,b,c] = d.version.split('.').map(Number);
  d.version = [a,b,c+1].join('.');
  writeFileSync(join(__dirname, f), JSON.stringify(d, null, 2) + '\n');
  console.log(d.name + '@' + d.version);
});
"
